// Witness endurance index — record JAH-GAIS-BODYCAM-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"battery_h": 12, "storage_gb": 128, "price_usd": 400};
var value = (m.battery_h*m.storage_gb/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAIS-BODYCAM-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAIS-BODYCAM-000001|' + value.toFixed(2) + ' endurance index');

